using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
public sealed partial class ResearchTools
{
    private readonly HttpClient _httpClient;
    private readonly List<NoteEntry> _notes = [];

    public ResearchTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public IReadOnlyList<NoteEntry> Notes => _notes;

    /// <summary>
    /// Returns the tool definitions for the research agent.
    /// </summary>
    public IList<AITool> AsTools() =>
    [
        AIFunctionFactory.Create(SearchWebAsync, name: "search_web"),
        AIFunctionFactory.Create(AddNote, name: "add_note"),
        AIFunctionFactory.Create(GetNotes, name: "get_notes"),
    ];

    [Description("Search the web for information on a query. Returns a list of result snippets with titles and URLs.")]
    private async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        // Use DuckDuckGo HTML search (no API key required)
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";

        var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

        try
        {
            var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();
            var html = await response.Content.ReadAsStringAsync(cancellationToken);

            var results = ParseSearchResults(html);
            if (results.Count == 0)
            {
                return "No results found.";
            }

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"");
            sb.AppendLine();
            foreach (var (title, snippet, link) in results.Take(5))
            {
                sb.AppendLine($"**{title}**");
                sb.AppendLine($"  {snippet}");
                sb.AppendLine($"  URL: {link}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Add a research note with a topic tag and content. Use this to record important findings.")]
    private string AddNote(
        [Description("A short topic tag for the note (e.g., 'key-finding', 'statistic', 'source')")] string topic,
        [Description("The content of the note")] string content)
    {
        var entry = new NoteEntry(topic, content, DateTime.UtcNow);
        _notes.Add(entry);
        return $"Note #{_notes.Count} added under topic '{topic}'.";
    }

    [Description("Retrieve all research notes taken so far. Use this before writing a summary.")]
    private string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes recorded yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"Research notes ({_notes.Count} total):");
        sb.AppendLine();
        for (var i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"  [{i + 1}] ({note.Topic}) {note.Content}");
        }

        return sb.ToString();
    }

    private static List<(string Title, string Snippet, string Url)> ParseSearchResults(string html)
    {
        var results = new List<(string, string, string)>();

        var titleMatches = ResultTitleRegex().Matches(html);
        var snippetMatches = SnippetRegex().Matches(html);

        var count = Math.Min(titleMatches.Count, snippetMatches.Count);
        for (var i = 0; i < count && i < 8; i++)
        {
            var rawUrl = titleMatches[i].Groups[1].Value;
            var title = StripHtml(titleMatches[i].Groups[2].Value);
            var snippet = StripHtml(snippetMatches[i].Groups[1].Value);

            // DuckDuckGo wraps URLs in a redirect; extract the actual URL
            var url = ExtractUrl(rawUrl);
            if (!string.IsNullOrWhiteSpace(title) && !string.IsNullOrWhiteSpace(snippet))
            {
                results.Add((title.Trim(), snippet.Trim(), url));
            }
        }

        return results;
    }

    private static string ExtractUrl(string rawUrl)
    {
        // DuckDuckGo redirect format: //duckduckgo.com/l/?uddg=<encoded_url>&...
        var match = UddgRegex().Match(rawUrl);
        if (match.Success)
        {
            return WebUtility.UrlDecode(match.Groups[1].Value);
        }

        return rawUrl.StartsWith("//") ? $"https:{rawUrl}" : rawUrl;
    }

    private static string StripHtml(string html)
    {
        var text = HtmlTagRegex().Replace(html, "");
        return WebUtility.HtmlDecode(text);
    }

    [GeneratedRegex("""<a[^>]+class="result__a"[^>]+href="([^"]*)"[^>]*>(.*?)</a>""", RegexOptions.Singleline)]
    private static partial Regex ResultTitleRegex();

    [GeneratedRegex("""<a[^>]+class="result__snippet"[^>]*>(.*?)</a>""", RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex("""uddg=([^&]+)""")]
    private static partial Regex UddgRegex();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex HtmlTagRegex();
}

public sealed record NoteEntry(string Topic, string Content, DateTime Timestamp);

