using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OpenAI API key via 'AI:ApiKey' in config or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddHttpClient<ResearchTools>();

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, apiKey));

builder.Services.AddSingleton<ResearchTools>(sp =>
    new ResearchTools(sp.GetRequiredService<IHttpClientFactory>().CreateClient(nameof(ResearchTools))));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

// Build the agent with tools
var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    "You are a thorough research assistant. When given a topic:\n" +
    "1. Search the web with multiple relevant queries to gather information.\n" +
    "2. Use the add_note tool to record key findings, statistics, and source URLs.\n" +
    "3. After gathering enough information, use get_notes to review your notes.\n" +
    "4. Provide a well-structured summary of your research with citations.\n" +
    "Be thorough — perform at least 2-3 different searches to cover the topic well.")
{
    Tools = tools.AsTools(),
};

Console.ForegroundColor = ConsoleColor.Cyan;
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║         AI Research Agent                ║");
Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching… (the agent will search the web and take notes)");
    Console.ResetColor();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
    };

    try
    {
        await foreach (var response in agent.InvokeStreamingAsync(messages, options))
        {
            if (!string.IsNullOrEmpty(response.Text))
            {
                Console.Write(response.Text);
            }
        }

        Console.WriteLine();
        Console.WriteLine();

        // Show recorded notes summary
        if (tools.Notes.Count > 0)
        {
            Console.ForegroundColor = ConsoleColor.Yellow;
            Console.WriteLine($"📝 {tools.Notes.Count} research note(s) recorded during this session.");
            Console.ResetColor();
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

