 using Microsoft.Extensions.AI;
 using Microsoft.Agents.AI;
 using OpenAI;
 using ResearchAgent;

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // Create the IChatClient from the OpenAI SDK via MEAI adapter
 var openAiClient = new OpenAIClient(apiKey);
 IChatClient innerClient = openAiClient.GetChatClient(modelId).AsIChatClient();

 var tools = new ResearchTools(new HttpClient());

 // Wrap with function invocation support (handles tool call loops)
 IChatClient chatClient = innerClient
     .AsBuilder()
     .UseFunctionInvocation(configure: opts =>
     {
         opts.MaximumIterationsPerRequest = 10;
     })
     .Build();

 // Build the agent
 var agent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a thorough research assistant. When given a topic:
         1. Search the web with multiple relevant queries to gather information.
         2. Use the add_note tool to record key findings, statistics, and source URLs.
         3. After gathering enough information, use get_notes to review your notes.
         4. Provide a well-structured summary of your research with citations.
         Be thorough — perform at least 2-3 different searches to cover the topic well.
         """,
     name: "ResearchAgent",
     description: "An agent that researches topics using web search and note-taking.",
     tools: tools.AsTools());

 Console.ForegroundColor = ConsoleColor.Cyan;
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║         AI Research Agent                ║");
 Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.ResetColor();
 Console.WriteLine();

 while (true)
 {
     Console.ForegroundColor = ConsoleColor.Green;
     Console.Write("Research topic> ");
     Console.ResetColor();

     var topic = Console.ReadLine()?.Trim();
     if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
     {
         break;
     }

     Console.ForegroundColor = ConsoleColor.DarkGray;
     Console.WriteLine("Researching… (the agent will search the web and take notes)");
     Console.ResetColor();

     try
     {
         var session = await agent.CreateSessionAsync(conversationId: Guid.NewGuid().ToString());

         await foreach (var update in agent.RunStreamingAsync(
             $"Research the following topic and provide a comprehensive summary: {topic}",
             session))
         {
             if (!string.IsNullOrEmpty(update.Text))
             {
                 Console.Write(update.Text);
             }
         }

         Console.WriteLine();
         Console.WriteLine();

         if (tools.Notes.Count > 0)
         {
             Console.ForegroundColor = ConsoleColor.Yellow;
             Console.WriteLine($"📝 {tools.Notes.Count} research note(s) recorded during this session.");
             Console.ResetColor();
         }
     }
     catch (Exception ex)
     {
         Console.ForegroundColor = ConsoleColor.Red;
         Console.WriteLine($"Error: {ex.Message}");
         Console.ResetColor();
     }

     Console.WriteLine();
 }

 Console.WriteLine("Goodbye!");

